parameters.jsCode:
const textoOriginal = String($json.text ?? '');

const formulario = $('Reunir formulario y vacante').item.json;

const normalizar = (valor = '') =>
  String(valor)
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/\s+/g, ' ')
    .trim();

const buscarValor = (...fragmentos) => {
  const campo = Object.entries(formulario).find(([nombreCampo]) =>
    fragmentos.some((fragmento) =>
      normalizar(nombreCampo).includes(normalizar(fragmento))
    )
  );

  return campo?.[1] == null ? '' : String(campo[1]).trim();
};

const nombre = buscarValor('nombre y apellido');

const correo = buscarValor(
  'correo electrónico de contacto',
  'correo electronico de contacto'
);

const telefono = buscarValor(
  'número de teléfono con código de área',
  'numero de telefono con codigo de area'
);

const escaparRegex = (valor) =>
  valor.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

const reemplazarValor = (texto, valor, reemplazo) => {
  if (!valor) return texto;

  return texto.replace(
    new RegExp(escaparRegex(valor), 'gi'),
    reemplazo
  );
};

let textoLimpio = textoOriginal;

// Nombre informado en el formulario
textoLimpio = reemplazarValor(
  textoLimpio,
  nombre,
  '[NOMBRE OMITIDO]'
);

// Nombres que aparecen después de títulos frecuentes del CV
textoLimpio = textoLimpio.replace(
  /((?:documento|curr[ií]culum(?:\s+vitae)?|cv)[^\n\r]{0,80}[\n\r]+\s*)([A-ZÁÉÍÓÚÑ][a-záéíóúñ]+(?:\s+[A-ZÁÉÍÓÚÑ][a-záéíóúñ]+){1,4})/gi,
  '$1[NOMBRE OMITIDO]'
);

// Correo informado en el formulario
textoLimpio = reemplazarValor(
  textoLimpio,
  correo,
  '[CORREO OMITIDO]'
);

// Teléfono informado en el formulario
textoLimpio = reemplazarValor(
  textoLimpio,
  telefono,
  '[TELÉFONO OMITIDO]'
);

// Otros correos presentes en el CV
textoLimpio = textoLimpio.replace(
  /\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b/gi,
  '[CORREO OMITIDO]'
);

// Enlaces, incluido LinkedIn
textoLimpio = textoLimpio.replace(
  /https?:\/\/\S+|www\.\S+/gi,
  '[ENLACE OMITIDO]'
);

// Otros números telefónicos
textoLimpio = textoLimpio.replace(
  /(?:\+?\d[\d\s().-]{7,}\d)/g,
  (coincidencia) =>
    coincidencia.replace(/\D/g, '').length >= 8
      ? '[TELÉFONO OMITIDO]'
      : coincidencia
);

// Fecha de nacimiento
textoLimpio = textoLimpio.replace(
  /(?:fecha\s+de\s+nacimiento|nacimiento)\s*:?\s*[^\n\r]*/gi,
  'Fecha de nacimiento: [OMITIDA]'
);

// Documento de identidad
textoLimpio = textoLimpio.replace(
  /(?:dni|documento(?:\s+de\s+identidad)?)\s*:?\s*[^\n\r]*/gi,
  'Documento: [OMITIDO]'
);

// Domicilio
textoLimpio = textoLimpio.replace(
  /(?:domicilio|direcci[oó]n)\s*:?\s*[^\n\r]*/gi,
  'Domicilio: [OMITIDO]'
);

// LinkedIn escrito sin URL completa
textoLimpio = textoLimpio.replace(
  /linkedin\s*:?\s*[^\n\r]*/gi,
  'LinkedIn: [OMITIDO]'
);

return {
  json: {
    ...$json,
    nombre_detectado: nombre,
    texto_cv_original: textoOriginal,
    texto_cv_seudonimizado: textoLimpio
  }
};

